<script setup>
import { Link } from '@inertiajs/vue3';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';

const props = defineProps({ reels: { type: Array, default: () => [] } });
const activeIndex = ref(-1), progress = ref(0), muted = ref(true), paused = ref(false), videoRef = ref(null), touchStart = ref({ x: 0, y: 0 });
let timer = null;
const isOpen = computed(() => activeIndex.value >= 0 && activeIndex.value < props.reels.length);
const current = computed(() => isOpen.value ? props.reels[activeIndex.value] : null);
const money = (value) => new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(value||0));
const priceText = (reel) => reel?.item_type === 'service' ? (reel.item?.price_label || 'Request a quote') : (reel?.item?.current_price ? money(reel.item.current_price) : '');
const labelText = (reel) => [reel?.item?.brand?.name,reel?.item?.category?.name].filter(Boolean).join(' · ') || (reel?.item_type === 'service' ? 'Prinx service' : 'Prinx product');
function clearTimer(){if(timer)window.clearInterval(timer);timer=null}
function startImageTimer(){clearTimer();const duration=Math.max(3,Number(current.value?.display_seconds||6))*1000;timer=window.setInterval(()=>{if(paused.value||!isOpen.value||current.value?.media_type==='video')return;progress.value=Math.min(100,progress.value+(50/duration)*100);if(progress.value>=100)next()},50)}
async function resetPlayback(){clearTimer();progress.value=0;paused.value=false;await nextTick();if(current.value?.media_type==='video'){const video=videoRef.value;if(video){video.currentTime=0;video.muted=muted.value;video.play().catch(()=>{paused.value=true})}}else if(isOpen.value)startImageTimer()}
function openReel(index){activeIndex.value=index}function close(){clearTimer();videoRef.value?.pause?.();activeIndex.value=-1;progress.value=0}function next(){if(activeIndex.value>=props.reels.length-1){close();return}activeIndex.value+=1}function previous(){if(activeIndex.value<=0)return;activeIndex.value-=1}
function togglePause(){paused.value=!paused.value;if(current.value?.media_type==='video'){if(paused.value)videoRef.value?.pause?.();else videoRef.value?.play?.().catch(()=>{paused.value=true})}}
function toggleMute(){muted.value=!muted.value;if(videoRef.value)videoRef.value.muted=muted.value}
function onVideoTimeUpdate(event){const video=event.target;if(Number.isFinite(video.duration)&&video.duration>0)progress.value=Math.min(100,(video.currentTime/video.duration)*100)}
function onTouchStart(event){const touch=event.changedTouches[0];touchStart.value={x:touch.clientX,y:touch.clientY}}function onTouchEnd(event){const touch=event.changedTouches[0],dx=touch.clientX-touchStart.value.x,dy=touch.clientY-touchStart.value.y;if(Math.abs(dy)>90&&dy>0&&Math.abs(dy)>Math.abs(dx)){close();return}if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))dx<0?next():previous()}
function onKeydown(event){if(!isOpen.value)return;if(event.key==='Escape')close();if(event.key==='ArrowRight')next();if(event.key==='ArrowLeft')previous();if(event.key===' '){event.preventDefault();togglePause()}}
watch(activeIndex,resetPlayback);watch(isOpen,(open)=>{if(typeof document!=='undefined')document.body.style.overflow=open?'hidden':''});onMounted(()=>window.addEventListener('keydown',onKeydown));onBeforeUnmount(()=>{clearTimer();window.removeEventListener('keydown',onKeydown);document.body.style.overflow=''})
</script>

<template>
<section v-if="reels.length" class="overflow-hidden bg-slate-950 py-12 text-white sm:py-14"><div class="container-shell"><div class="flex items-end justify-between gap-5"><div><p class="text-xs font-black uppercase tracking-[.2em] text-prinx-400">Watch & shop</p><h2 class="mt-2 text-2xl font-black tracking-tight sm:text-3xl">Product reels</h2><p class="mt-2 max-w-xl text-sm leading-6 text-slate-400">Quick product views, demonstrations and service highlights.</p></div><span class="hidden rounded-[10px] border border-white/10 bg-white/5 px-3 py-2 text-xs font-bold text-slate-300 sm:inline-flex">Tap a reel to watch</span></div><div class="scrollbar-hidden mt-7 flex snap-x snap-mandatory gap-3 overflow-x-auto pb-2 sm:gap-4"><button v-for="(reel,index) in reels" :key="reel.id" type="button" class="group relative aspect-[9/14] w-[42vw] max-w-[168px] shrink-0 snap-start overflow-hidden rounded-[10px] border border-white/10 bg-[radial-gradient(circle_at_50%_35%,#fff7ed_0%,#fed7aa_35%,#1e293b_82%)] text-left shadow-[0_18px_45px_rgba(0,0,0,.3)] sm:w-[180px] sm:max-w-none lg:w-[190px]" @click="openReel(index)"><img :src="reel.cover_url" :alt="`${reel.title} product reel`" loading="lazy" decoding="async" :class="['absolute inset-0 h-full w-full transition duration-500 group-hover:scale-105',reel.media_type==='image'?'object-contain p-3':'object-cover']"><div class="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/15 to-slate-950/10"></div><div class="absolute left-2.5 top-2.5 flex h-9 w-9 items-center justify-center rounded-full border-2 border-prinx-400 bg-slate-950/65 text-white shadow-lg backdrop-blur">▶</div><span v-if="reel.media_type==='video'" class="absolute right-2.5 top-2.5 rounded-[7px] bg-black/55 px-2 py-1 text-[9px] font-black uppercase tracking-[.14em] backdrop-blur">Video</span><div class="absolute inset-x-0 bottom-0 p-3"><p class="truncate text-[9px] font-black uppercase tracking-[.14em] text-prinx-300">{{ labelText(reel) }}</p><h3 class="mt-1 line-clamp-2 text-sm font-black leading-5 text-white">{{ reel.title }}</h3><p class="mt-2 text-xs font-black text-white">{{ priceText(reel) }}</p></div></button></div></div>
<div v-if="isOpen" class="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/96 p-0 backdrop-blur-md sm:p-5" role="dialog" aria-modal="true" :aria-label="current?.title" @touchstart.passive="onTouchStart" @touchend.passive="onTouchEnd"><button type="button" class="absolute inset-0 cursor-default" aria-label="Close reels" @click="close"></button><button v-if="activeIndex>0" type="button" class="absolute left-4 z-20 hidden h-11 w-11 items-center justify-center rounded-full border border-white/15 bg-black/45 text-2xl text-white backdrop-blur sm:flex" @click.stop="previous">‹</button><button v-if="activeIndex<reels.length-1" type="button" class="absolute right-4 z-20 hidden h-11 w-11 items-center justify-center rounded-full border border-white/15 bg-black/45 text-2xl text-white backdrop-blur sm:flex" @click.stop="next">›</button><div class="relative z-10 h-[100dvh] w-full max-w-[430px] overflow-hidden bg-black shadow-2xl sm:h-auto sm:aspect-[9/16] sm:max-h-[92dvh] sm:rounded-[10px] sm:border sm:border-white/10" @click.stop><div class="absolute inset-x-0 top-0 z-30 p-3"><div class="flex gap-1"><div v-for="(reel,index) in reels" :key="reel.id" class="h-0.5 flex-1 overflow-hidden rounded-full bg-white/25"><div class="h-full bg-white transition-[width] duration-75" :style="{width:index<activeIndex?'100%':index===activeIndex?`${progress}%`:'0%'}"></div></div></div><div class="mt-3 flex items-center justify-between gap-3"><div class="flex min-w-0 items-center gap-2.5"><div class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border-2 border-prinx-400 bg-white p-1"><img :src="current.item?.image_url" :alt="current.item?.name" class="h-full w-full rounded-full object-contain"></div><div class="min-w-0"><p class="truncate text-xs font-black text-white">Prinx Electronics</p><p class="truncate text-[10px] font-semibold text-white/65">{{ labelText(current) }}</p></div></div><div class="flex items-center gap-2"><button type="button" class="flex h-9 w-9 items-center justify-center rounded-full bg-black/40 text-white" @click="togglePause">{{ paused?'▶':'Ⅱ' }}</button><button v-if="current.media_type==='video'" type="button" class="flex h-9 w-9 items-center justify-center rounded-full bg-black/40 text-white" @click="toggleMute">{{ muted?'🔇':'🔊' }}</button><button type="button" class="flex h-9 w-9 items-center justify-center rounded-full bg-black/40 text-lg text-white" @click="close">×</button></div></div></div><video v-if="current.media_type==='video'" ref="videoRef" :key="current.id" :src="current.media_url" :poster="current.cover_url" class="absolute inset-0 h-full w-full object-cover" playsinline preload="metadata" :muted="muted" @timeupdate="onVideoTimeUpdate" @ended="next" @click="togglePause"></video><template v-else><img :src="current.media_url" alt="" aria-hidden="true" class="absolute inset-0 h-full w-full scale-110 object-cover opacity-45 blur-2xl"><div class="absolute inset-0 bg-black/25"></div><img :src="current.media_url" :alt="current.title" class="absolute inset-0 h-full w-full object-contain" @click="togglePause"></template><div class="absolute inset-x-0 bottom-0 z-20 bg-gradient-to-t from-black via-black/75 to-transparent px-4 pb-5 pt-24 text-white"><p class="text-[10px] font-black uppercase tracking-[.16em] text-prinx-300">{{ current.item_type==='product'?'Featured product':'Featured service' }}</p><h3 class="mt-2 text-xl font-black leading-tight">{{ current.title }}</h3><p v-if="current.caption" class="mt-2 line-clamp-3 text-sm leading-6 text-white/75">{{ current.caption }}</p><div class="mt-4 flex items-center justify-between gap-3"><div><p class="text-lg font-black">{{ priceText(current) }}</p></div><Link :href="current.item_url" class="inline-flex shrink-0 items-center justify-center rounded-[10px] bg-prinx-500 px-4 py-3 text-sm font-black text-white">{{ current.cta_label }} →</Link></div></div></div></div></section>
</template>
